## Handling Network Images

### Download for PPTX Export

```javascript
async function downloadImage(url) {
  const response = await fetch(url);
  const buffer = await response.arrayBuffer();
  return Buffer.from(buffer);
}

// Use in pptxgenjs
const imageData = await downloadImage(imageUrl);
slide.addImage({
  data: imageData.toString('base64'),
  x: 1, y: 2, w: 4, h: 3
});
```

### Error Handling

```javascript
async function safeAddImage(slide, imageSource, options) {
  try {
    if (imageSource.startsWith('http')) {
      const imageData = await downloadImage(imageSource);
      slide.addImage({
        data: imageData.toString('base64'),
        ...options
      });
    } else {
      slide.addImage({
        path: imageSource,
        ...options
      });
    }
  } catch (error) {
    console.warn(`Failed to load image: ${imageSource}`);
    // Add placeholder text
    slide.addText('[图片加载失败]', {
      x: options.x,
      y: options.y,
      w: options.w,
      h: options.h,
      align: 'center',
      valign: 'middle'
    });
  }
}
```

